/// <summary>
/// Business event triggered when a transfer order is shipped.
/// </summary>
[BusinessEvents(classStr(AAXTransferOrderShippedBusinessEventContract), 'TransferOrderShippedBusinessEventName', 'TransferOrderShippedBusinessEventDescription', ModuleAxapta::Inventory)]
public final class AAXTransferOrderShippedBusinessEvent extends BusinessEventsBase
{
    private InventTransferTable inventTransferTable;

}

Method.Source:
/// <summary>
/// Gets or sets the source InventTransferTable for building the event contract.
/// </summary>
private InventTransferTable parmInventTransferTable(InventTransferTable _inventTransferTable = inventTransferTable)
{
    inventTransferTable = _inventTransferTable;

    return inventTransferTable;
}

/// <summary>
/// Creates a new <c>AAXTransferOrderShippedBusinessEvent</c> instance from the specified <c>InventTransferTable</c> record.
/// </summary>
/// <param name="_inventTransferTable">The source InventTransferTable record.</param>
/// <returns>A new instance of <c>AAXTransferOrderShippedBusinessEvent</c>.</returns>
public static AAXTransferOrderShippedBusinessEvent newFromInventTransferTable(InventTransferTable _inventTransferTable)
{
    AAXTransferOrderShippedBusinessEvent businessEvent = new AAXTransferOrderShippedBusinessEvent();
    businessEvent.parmInventTransferTable(_inventTransferTable);

    return businessEvent;
}

/// <summary>
/// Private constructor. Use static factory methods to create instances.
/// </summary>
private void new()
{
}

/// <summary>
/// Builds the data contract for this business event.
/// </summary>
/// <returns>The populated <c>AAXTransferOrderShippedBusinessEventContract</c>.</returns>
[Wrappable(true), Replaceable(true)]
public BusinessEventsContract buildContract()
{
    return AAXTransferOrderShippedBusinessEventContract::newFromInventTransferTable(inventTransferTable);
}
